class Cell:
    def __init__(self):
        self._dependents = []


class InputCell(Cell):
    def __init__(self, initial_value):
        super().__init__()
        self._value = initial_value

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        self._value = new_value
        self._recompute_dependents()

    def _recompute_dependents(self):
        queue = list(self._dependents)
        seen = set()
        while queue:
            cell = queue.pop(0)
            if id(cell) in seen:
                continue
            seen.add(id(cell))
            old_value = cell._value
            cell._value = cell._compute([dep.value for dep in cell._inputs])
            if cell._value != old_value:
                for callback in cell._callbacks:
                    callback(cell._value)
            queue.extend(cell._dependents)


class ComputeCell(Cell):
    def __init__(self, inputs, compute_function):
        super().__init__()
        self._inputs = inputs
        self._compute = compute_function
        self._callbacks = []
        for cell in inputs:
            cell._dependents.append(self)
        self._value = compute_function([cell.value for cell in inputs])

    @property
    def value(self):
        return self._value

    def add_callback(self, callback):
        self._callbacks.append(callback)

    def remove_callback(self, callback):
        try:
            self._callbacks.remove(callback)
        except ValueError:
            pass

